      const at = info && info.chests[ch.v ? "v:" + ch.v : ch.id];
      const p = at ? toFloor(floor, room, at.x, at.y, info.w, info.h) : toFloor(floor, room, ch.x, ch.y, data.w, data.h);
      if (!p) continue;
      const cell = { x: Math.floor(p.x), y: Math.floor(p.y) };
