  // the title screen's big picture of Lea (seen from behind, hair blowing) has four blues, darkest first
  const TITLE_HAIR = [[0x1f, 0x06, 0x6f], [0x2d, 0x1b, 0xaf], [0x3e, 0x6a, 0xd9], [0x9c, 0xb8, 0xfd]];
  const TITLE_BY_ELEMENT = {
    1: [[0x5c, 0x10, 0x06], [0xa8, 0x24, 0x0c], [0xe2, 0x5c, 0x1c], [0xff, 0xc2, 0x8a]],
    2: [[0x1c, 0x4c, 0x70], [0x34, 0x78, 0xb4], [0x6e, 0xc0, 0xea], [0xdc, 0xf6, 0xff]],
    3: [[0x34, 0x10, 0x6a], [0x58, 0x1e, 0xb0], [0x8c, 0x52, 0xe2], [0xd2, 0xb2, 0xff]],
    4: [[0x0a, 0x48, 0x30], [0x14, 0x78, 0x46], [0x30, 0xb8, 0x6a], [0xaa, 0xf0, 0xc4]]
  };
  const LEA_SHEETS = /^media\/entity\/player\/(move|throw|poses|move-weak|hugging|sleeping|special|item-hold)\.png$/;
