        if (!kind) { if (st && img.data !== st.orig && Object.values(st.variants).includes(img.data)) img.data = st.orig; continue; }
        // a fresh picture from the game (first time, or after it reloaded its images)
        if (!st || (img.data !== st.orig && !Object.values(st.variants).includes(img.data))) { st = { orig: img.data, variants: {}, kind }; hairState.set(img, st); }
