    B.setAlign(left ? ig.GUI_ALIGN.X_LEFT : ig.GUI_ALIGN.X_RIGHT, ig.GUI_ALIGN.Y_TOP); B.setHeight(26); B.textChild.setPos(0, -1); B.setPos(2, 2);
