              this.wdnSummary.hook.transitions = { DEFAULT: { state: {}, time: 0.15, timeFunction: KEY_SPLINES.EASE }, HIDDEN: { state: { alpha: 0, offsetX: -12 }, time: 0.12, timeFunction: KEY_SPLINES.LINEAR } };
