  // ---------- the health-bar look, for every panel and pop-up ----------
  // A black plate with the HP bar's slanted corners (top right and bottom left cut at 45 degrees), a dark
  // outer edge and the thin grey track just inside, like the minimap frame and the clock. Drawn once per
  // size into a picture and reused. accent: a colour for the track instead of grey (gold for new things).
  const plateCache = {};
  function plateImage(w, h, accent, cut) {
    w = Math.max(8, Math.round(w)); h = Math.max(8, Math.round(h));
    cut = cut == null ? Math.min(10, Math.floor(Math.min(w, h) / 3)) : cut;
    const key = w + "x" + h + ":" + (accent || "") + ":" + cut;
    if (plateCache[key]) return plateCache[key];
    const c = document.createElement("canvas"); c.width = w; c.height = h;
    const cx = c.getContext("2d"), img = cx.createImageData(w, h), px = img.data;
    const inside = (x, y, inset) => x >= inset && y >= inset && x < w - inset && y < h - inset
      && x - y <= w - 1 - inset - cut && y - x <= h - 1 - inset - cut;
    const tr = accent ? accent.match(/\d+/g).map(Number) : [80, 80, 80];
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      if (!inside(x, y, 0)) continue;
      const i = (y * w + x) * 4;
      let col = [0, 0, 0];
      if (!inside(x, y, 1)) col = [24, 24, 24];                                       // outer edge
      else if (inside(x, y, 2) && !inside(x, y, 3)) col = tr;                         // the track
      px[i] = col[0]; px[i + 1] = col[1]; px[i + 2] = col[2]; px[i + 3] = 255;
    }
    cx.putImageData(img, 0, 0);
    // at the game's pixel scale, so it stays crisp
    const k = (ig.system && ig.system.scale) || 1;
    let data = c;
    if (k !== 1) { data = document.createElement("canvas"); data.width = w * k; data.height = h * k; const d = data.getContext("2d"); d.imageSmoothingEnabled = false; d.drawImage(c, 0, 0, data.width, data.height); }
    const im = new ig.Image({}); im.data = data; im.width = w; im.height = h; im.loaded = true;
    return (plateCache[key] = im);
  }
  function drawPlate(r, x, y, w, h, alpha, accent, cut) {
    try { const im = plateImage(w, h, accent, cut); r.addGfx(im, Math.round(x), Math.round(y), 0, 0, im.width, im.height).setAlpha(alpha == null ? 0.92 : alpha); }
    catch (e) { r.addColor("#000", x, y, w, h).setAlpha(alpha == null ? 0.85 : alpha); }
  }
