  // ---------- "Restart game" in the pause menu ----------
  // Reloads the whole game (and so every mod) without closing it. Unless you're in a cutscene, your exact spot
  // is written to the autosave first, so Continue on the title screen picks up right where you were.
  function restartGame() {
    let saved = false;
    try {
      if (opt("restartResume", true) !== false && sc.model.isGame() && !sc.model.isCutscene() && (!sc.model.isSaveAllowed || sc.model.isSaveAllowed()) && ig.game.playerEntity) {
        const b = {};
        ig.storage._saveState(b, null, null);   // null position: Lea's exact spot right now
        ig.storage.saveAutoSlot(b);
        saved = true;
      }
    } catch (e) { console.error("[CrossCode Enhanced] restart: couldn't save", e); saved = false; }
    // wait for the save file to finish writing, then reload
    const d = ig.storage && ig.storage.data, t0 = Date.now();
    const go = () => {
      const busy = d && (d.ioState || (d.saveDataStack && d.saveDataStack.length));
      if (busy && Date.now() - t0 < 5000) { setTimeout(go, 50); return; }
      if (relaunch()) return;
      try { window.location.reload(); } catch (e) {}
    };
    setTimeout(go, 150);
  }
  // A real restart: a fresh copy of the game is started (after a two second wait) and this one closes. Reloading
  // the page in place (the old way) never gives back all of the old game's memory, so every restart made the
  // next start slower until the game ran out and crashed.
  function relaunch() {
    try {
      if (!window.require || !window.nw || !nw.App) return false;
      const cp = window.require("child_process"), exe = process.execPath;
      if (!exe) return false;
      let child;
      if (process.platform === "win32") {
        // a tiny Windows script waits two seconds then starts the game; scripts run by wscript have no window
        const fs = window.require("fs"), path = window.require("path"), os = window.require("os");
        const vbs = path.join(os.tmpdir(), "crosscode-restart.vbs");
        const q = v => '"' + String(v).replace(/"/g, '""') + '"';   // (a VBScript string)
        fs.writeFileSync(vbs, "WScript.Sleep 2000\r\nSet sh = CreateObject(\"WScript.Shell\")\r\nsh.CurrentDirectory = " + q(process.cwd()) + "\r\nsh.Run " + q(q(exe)) + ", 1, False\r\n");
        child = cp.spawn("wscript.exe", [vbs], { detached: true, stdio: "ignore", windowsHide: true, cwd: process.cwd() });
      } else child = cp.spawn("sh", ["-c", 'sleep 2; "' + exe + '" >/dev/null 2>&1 &'], { detached: true, stdio: "ignore", cwd: process.cwd() });
      child.unref();
      setTimeout(() => { try { nw.App.quit(); } catch (e) { try { window.close(); } catch (e2) {} } }, 150);
      return true;
    } catch (e) { console.error("[CrossCode Enhanced] restart", e); return false; }
  }
