            updateDrawables(r) {
              const cx = 7, cy = 7;
              for (let dy = -6; dy <= 6; dy++) { const hw = Math.round(Math.sqrt(Math.max(0, 42 - dy * dy))); r.addColor("rgb(14,12,18)", cx - hw, cy + dy, hw * 2 + 1, 1); }
              for (let dy = -5; dy <= 5; dy++) { const hw = Math.round(Math.sqrt(Math.max(0, 30 - dy * dy))); r.addColor("rgb(52,52,66)", cx - hw, cy + dy, hw * 2 + 1, 1); }
              const G = "rgb(64,226,170)";
              for (let k = 0; k <= 6; k++) { const y = cy - 3 + k, hw = Math.floor(k / 2); r.addColor(G, cx - hw, y, 1, 1); r.addColor(G, cx + hw, y, 1, 1); }
              r.addColor(G, cx - 3, cy + 3, 7, 1);
            }
