        textGui(c, "\\c[4]Defense\\c[0]", small, 94, 130); textGui(c, num(p.defense), small, 144, 130);
        textGui(c, "\\c[4]Focus\\c[0]", small, 12, 144); textGui(c, num(p.focus), small, 62, 144);
        textGui(c, "\\c[4]EXP\\c[0]", small, 94, 144); textGui(c, num(g.exp), small, 144, 144);
        textGui(c, "\\c[4]Credits\\c[0]", small, 12, 158); textGui(c, num(g.credit), small, 62, 158);
        // weaknesses and resistances (the element icons from the game's font)
