        row("Card collected", got && got.d != null ? "Day " + got.d : "Before cards");
        if (hasShiny(info.key)) row("Shiny collected", "Day " + got.sh);
        const kills = killsOf(info.key);
        row("Kills", kills);
        {   // the game card: which copy, its numbers and its arrows (drawn as a little 3x3 compass)
          const cps = copiesOf(info.key), fi = isShiny ? -1 : favCopy(info.key), arr = lvArrows(info.key, isShiny ? shinyArrows(info.key) : cps[fi]);
          const label = isShiny ? "Shiny copy" : "Copy " + (fi + 1) + "/" + cps.length + (cps.length > 1 ? " \\c[4](\\i[circle-left]\\i[circle-right])\\c[0]" : "");
          const gy = y, st = lvStats(info.key, isShiny);
          row(label, null);
          const sv = textGui(S, statText(st), small, 0, gy);
          sv.setPos(176 - 8 - 11 - 5 - sv.hook.size.x, gy);   // left of the arrow compass
          const glyph = new (ig.GuiElementBase.extend({ updateDrawables(r) {
            r.addColor("rgb(14,12,18)", 0, 0, 11, 11);
            for (let d = 0; d < 8; d++) {
              const [dx, dy] = DIRS[d], on = arr & (1 << d);
              r.addColor(on ? "rgb(255,214,96)" : "rgb(50,52,64)", 4 + dx * 4, 4 + dy * 4, 3, 3);
            }
            r.addColor("rgb(120,126,150)", 4, 4, 3, 3);
          } }))();
          glyph.setSize(11, 11); glyph.setPos(176 - 8 - 11, gy); S.addChildGui(glyph);
        }
        const next = MEDAL[medal + 1];
        row("Medal", (medal ? MEDAL[medal][0] : "None") + (next ? "  \\c[4](" + next[0] + " at " + next[2] + ")\\c[0]" : ""));
        {   // the card's level and EXP, with a little bar
          const X = cardXpInfo(info.key), gy = y;
          row("Level", !X.need ? "Lv " + X.lv + "  \\c[3]MAX\\c[0]" : "Lv " + X.lv + "  \\c[4]" + Math.floor(X.cur) + "/" + X.need + "\\c[0]");
          const bar = new (ig.GuiElementBase.extend({ updateDrawables(r) {
            const k = X.need ? Math.min(1, X.cur / X.need) : 1;
            r.addColor("rgb(14,12,18)", 0, 0, 160, 4); r.addColor("rgb(60,60,66)", 1, 1, 158, 2);
            r.addColor(X.need ? "rgb(96,180,255)" : "rgb(255,214,96)", 1, 1, Math.round(158 * k), 2);
          } }))();
          // a thin bar under the row, the width of the panel, so it never runs into the numbers
          bar.setSize(160, 4); bar.setPos(8, gy + 11); S.addChildGui(bar);
          y += 4;
        }
        y += 3;
        textGui(S, "FOUND IN", tiny, 8, y); y += 10;
        const set = areaSets()[info.area];
        textGui(S, (info.area ? areaLabel(info.area) : "\\c[4]-\\c[0]") + (set ? "  \\c[4]set " + set.filter(hasCard).length + "/" + set.length + (areaComplete(info.area) ? " - complete!" : "") + "\\c[0]" : ""), small, 8, y); y += 13;
        y += 3;
        textGui(S, "EQUIP", tiny, 8, y); y += 10;
