  function defineBounties() {
    if (BountyMenu) return true;
    if (!window.sc || !sc.BaseMenu || !sc.TextGui || !sc.ButtonGroup) return false;
    try { boardImage(); } catch (e) {}
    const tiny = () => sc.fontsystem.tinyFont, small = () => sc.fontsystem.smallFont;
    const X = 74, W = 420, Y0 = 50, RH = 64;
    // one bounty: select it, press to accept (or give it up)
    const Row = ig.FocusGui.extend({
      init(i) { this.parent(); this.i = i; this.setSize(W, RH - 4); },
      focusGained() { this.parent(); if (this.menu) this.menu.rowFocus(this.i); },
      onButtonPress() { if (this.menu) this.menu.rowPress(this.i); },
      updateDrawables(r) {
        if (!this.focus) return;
        const a = 0.55 + 0.35 * Math.sin(nowS() * 6), w = this.hook.size.x, h = this.hook.size.y;
        for (const [x, y, ww, hh] of [[0, 0, w, 2], [0, h - 2, w, 2], [0, 0, 2, h], [w - 2, 0, 2, h]]) r.addColor("#fff", x, y, ww, hh).setAlpha(a);
      }
    });
    BountyMenu = sc.BaseMenu.extend({
      kids: null, group: null,
      init() {
        this.parent();
        this.hook.size.x = ig.system.width; this.hook.size.y = ig.system.height;
        this.kids = [];
        // a menu needs at least one button for the controls to work: a Close button
        this.group = smartNav(new sc.ButtonGroup());
        this.group.setMouseFocusLostCallback(() => {});
        this.closeBtn = new sc.ButtonGui("Close", 80);
        this.closeBtn.onButtonPress = () => { try { sc.BUTTON_SOUND.back.play(); } catch (e) {} this.close(); };
        this.closeBtn.wdnFull = "Close the bounty list";
        this.allBtn = new sc.ButtonGui("\\i[help2]Accept all", 110);
        this.allBtn.onButtonPress = () => this.acceptAll();
        this.allBtn.wdnFull = "Accept every bounty you haven't accepted yet";
        this.addChildGui(this.allBtn); this.addChildGui(this.closeBtn);
        this.rows = [];
        this.doStateTransition("DEFAULT");
      },
      txt(t, font, x, y, maxW) { const g = textGui(this, t, font, x, y, maxW); this.kids.push(g); return g; },
      rowFocus(i) {
        const b = bounty.list[i];
        if (!b) return;
        try { sc.menu.setInfoText(b.done ? "Done! The reward is yours." : (b.acc ? "Accepted: press to give it up (your progress is kept)." : "Press to accept this bounty. Only accepted bounties count.") + "  \\i[help3] " + (b.track ? "Stop tracking" : "Track it: its hunting grounds go on your maps, and you'll hear how it's going")); } catch (e) {}
      },
      rowPress(i) {
        const b = bounty.list[i];
        if (!b || b.done) { try { sc.BUTTON_SOUND.denied.play(); } catch (e) {} return; }
        b.acc = !b.acc;
        try { sc.BUTTON_SOUND[b.acc ? "submit" : "back"].play(); } catch (e) {}
        this.build(i, 0);
      },
      toggleTrack(i) {
        const b = bounty.list[i];
        if (!b || b.done) { try { sc.BUTTON_SOUND.denied.play(); } catch (e) {} return; }
        const on = !b.track;
        for (const x of bounty.list) x.track = false;
        b.track = on;
        if (on) { b.acc = true; clearQuestFavourites(); }   // tracking a bounty takes it on too, and replaces a tracked quest
        try { sc.BUTTON_SOUND.submit.play(); } catch (e) {}
        this.build(i);
      },
      acceptAll() {
        let n = 0;
        for (const b of bounty.list) if (!b.done && !b.acc) { b.acc = true; n++; }
        try { sc.BUTTON_SOUND[n ? "submit" : "denied"].play(); } catch (e) {}
        this.build();
      },
      // rebuild everything; focus row fy (or the first bounty not yet accepted)
      build(fy0) {
        for (const k of this.kids) this.removeChildGui(k);
        this.kids = [];
        for (const rw of this.rows) this.removeChildGui(rw);
        this.rows = [];
        this.group.clear();
        bountyDay();
        const day = bounty.day || dayNum();
        this.head = this.txt("Day " + day + " bounties", sc.fontsystem.font, X + 6, 28);
        this.txt("\\c[4]New ones each morning: unfinished bounties end with the day\\c[0]", tiny(), X + 160, 33);
        bounty.list.forEach((b, i) => {
          const y = Y0 + i * RH;
          this.txt((b.done ? "\\c[2]" : "") + bountyText(b) + (b.done ? "\\c[0]" : ""), sc.fontsystem.font, X + 42, y + 6, 280);
          this.txt("\\c[4]" + bountyHint(b) + "\\c[0]", tiny(), X + 42, y + 24, W - 52);
          this.txt(Math.min(b.have || 0, b.need) + "\\c[4]/" + b.need + "\\c[0]", small(), X + 252, y + 33);
          this.txt("Reward  \\c[3]" + bountyReward(b) + "\\c[0]", small(), X + 42, y + 45, W - 52);
          if (b.done) this.txt("\\c[2]COMPLETE\\c[0]", small(), X + W - 62, y + 7);
          else if (b.acc) this.txt(b.track ? "\\c[2]TRACKED\\c[0]" : "\\c[3]ACCEPTED\\c[0]", small(), X + W - 62, y + 7);
          else this.txt("\\c[4]Not accepted\\c[0]", small(), X + W - 76, y + 7);
          const rw = new Row(i);
          rw.menu = this; rw.setPos(X, y);
          this.addChildGui(rw); this.rows.push(rw);
          this.group.addFocusGui(rw, 0, i);
        });
        if (!bounty.list.length) this.txt("\\c[4]No bounties yet: they appear once you're out in the world.\\c[0]", small(), X + 12, Y0 + 10);
        const fy = Y0 + 3 * RH + 4;
        this.txt("Finish all three: \\c[3]+" + allBonus() + " Credits\\c[0]", small(), X + 12, fy + 6);
        this.txt("\\c[4]Bounties done\\c[0] " + (bounty.total || 0) + "    \\c[4]Days cleared in a row\\c[0] " + (bounty.lastAll != null && bounty.lastAll >= day - 1 ? bounty.streak || 0 : 0), small(), X + 12, fy + 20);
        // the buttons go under the rows, and the controls start on the first bounty you haven't accepted
        const n = bounty.list.length;
        this.allBtn.setPos(X + W - 202, fy + 7); this.closeBtn.setPos(X + W - 86, fy + 7);
        this.group.addFocusGui(this.allBtn, 0, n); this.group.addFocusGui(this.closeBtn, 1, n);
        let want = typeof fy0 === "number" ? fy0 : bounty.list.findIndex(b => !b.done && !b.acc);
        const at = want >= 0 && want < n ? [0, want] : [1, n];
        this.allBtn.setActive(bounty.list.some(b => !b.done && !b.acc));
        try { this.group.focusCurrentButton(at[0], at[1], false, false, false, true); } catch (e) {}
      },
      updateDrawables(r) {
        drawPlate(r, X, 24, W, 20, 0.85, null, 5);
        bounty.list.forEach((b, i) => {
          const y = Y0 + i * RH;
          drawPlate(r, X, y, W, RH - 4, 0.9, b.done ? "rgb(92,190,110)" : i === 2 ? GOLD_TRACK : null);
          drawStars(r, X + 10, y + 9, i + 1, b.done ? "rgb(140,230,150)" : "rgb(255,208,64)");
          // progress bar
          const bx = X + 42, by = y + 36, bw = 204, k = Math.min(1, (b.have || 0) / b.need);
          r.addColor("rgb(14,12,18)", bx - 1, by - 1, bw + 2, 7);
          r.addColor("rgb(60,60,66)", bx, by, bw, 5);
          if (k > 0) { r.addColor(b.done ? "rgb(92,200,110)" : "rgb(232,182,58)", bx, by, Math.round(bw * k), 5); r.addColor("#fff", bx, by, Math.round(bw * k), 1).setAlpha(0.35); }
          if (b.card) {   // the reward card, small, on the right
            r.addTransform().setTranslate(X + W - 40, y + 20);
            drawCardBack(r, 26, 34, b.tier === 2);
            r.undoTransform();
          }
        });
        drawPlate(r, X, Y0 + 3 * RH + 4, W, 36, 0.85, null, 5);
      },
      // opened from a board: the main menu adds its own "back = leave" after the sub-menu is shown, so ours
      // goes on top here and closes the menu straight back to the game
      onPostDirectEnter() { if (this.direct) sc.menu.pushBackCallback(() => this.close()); },
      close() {
        if (this.direct) { try { sc.menu.popBackCallback(); } catch (e) {} try { sc.model.enterPrevSubState(); } catch (e) {} }
        else { try { sc.menu.popBackCallback(); } catch (e) {} try { sc.menu.popMenu(); } catch (e) {} }
      },
      showMenu() {
        this.direct = boardDirect; boardDirect = false;
        sc.menu.buttonInteract.pushButtonGroup(this.group);
        this.visibleNow = true;
        try { this.build(); } catch (e) { dbg("bounty list error: " + (e && e.stack)); }
        if (!this.direct) sc.menu.pushBackCallback(() => this.close());
        sc.menu.moveLeaSprite(0, 0, sc.MENU_LEA_STATE.HIDDEN);
        ig.interact.setBlockDelay(0.2);
        this.doStateTransition("DEFAULT");
      },
      hideMenu() { sc.menu.moveLeaSprite(0, 0, sc.MENU_LEA_STATE.LARGE); this.exitMenu(); },
      update() {
        this.parent && this.parent();
        try {
          if (!this.visibleNow) return;
          if (sc.control.menuHotkeyHelp2()) this.acceptAll();
          else if (sc.control.menuHotkeyHelp3()) { const c = this.group.current; if (c && c.x === 0 && this.rows[c.y]) this.toggleTrack(c.y); }
        } catch (e) {}
      },
      exitMenu() { this.visibleNow = false; try { sc.menu.buttonInteract.removeButtonGroup(this.group); } catch (e) {} this.doStateTransition("HIDDEN"); },
      modelChanged() {}
    });
    sc.MENU_SUBMENU.WDN_BOUNTIES = BOUNTY_MENU_ID;
    sc.SUB_MENU_INFO[BOUNTY_MENU_ID] = { Clazz: BountyMenu, name: "wdnBounties" };
    return true;
  }

  // ---- talking to a card player ----
  function npcPlayer(npc) {
    try {
      if (!duelsOn() || !npc || !npc.__wdnSpawn) return null;
      const map = String(ig.game.mapName || "").replace(/\//g, ".");
      for (const P of CARD_PLAYERS) {
        if (P.map !== map || P.char !== npc.characterName) continue;
        if (Math.abs(npc.__wdnSpawn.x - P.x) <= 8 && Math.abs(npc.__wdnSpawn.y - P.y) <= 8) return P;
      }
    } catch (e) {}
    return null;
  }
  // ---- innkeepers: talk to one to rest (until 08:00 or 20:00, fully healed) ----
  // The Rookie Harbor and Bergen desk clerks normally have nothing to say; the Cave Inn's Lings keep their
  // own conversation as a "Talk" choice.
  const INNKEEPERS = [
    { map: "rookie-harbor.inner-inn", char: "rookie-harbor.female-tall-black", x: 396, y: 160 },
    { map: "bergen.inn", char: "bergen.male-tall-bald-brown", x: 500, y: 224 },
    { map: "forest.interior.inn-01", char: "forest.family-father", x: 488, y: 272, name: "Sai Ling", talks: true },
    { map: "forest.interior.inn-og-02", char: "forest.family-mother", x: 420, y: 308, name: "Dar Ling", talks: true }
  ];
  function innkeeper(npc) {
    try {
      if (opt("inns", true) === false || !npc || !npc.__wdnSpawn || !window.wdnInnRest) return null;
      const map = String(ig.game.mapName || "").replace(/\//g, ".");
      return INNKEEPERS.find(K => K.map === map && K.char === npc.characterName && Math.abs(npc.__wdnSpawn.x - K.x) <= 8 && Math.abs(npc.__wdnSpawn.y - K.y) <= 8) || null;
    } catch (e) { return null; }
  }
  // the button press that closes a dialog (No, Leave) would otherwise talk to the innkeeper again straight
  // away, so innkeepers don't respond until a moment after the last dialog has gone
  let lastModal = 0;
  setInterval(() => {
    try {
      if (!window.ig || !ig.gui || !sc.ModalButtonInteract) return;
      for (const h of ig.gui.guiHooks) { const g = h && h.gui; if (g && (g instanceof sc.ModalButtonInteract || (sc.ModalScreenInteract && g instanceof sc.ModalScreenInteract))) { lastModal = Date.now(); return; } }
    } catch (e) {}
  }, 50);
  window.wdnLastModal = () => lastModal;
  // the innkeepers speak in the game's own message boxes, with their faces (a question: Lea picks an answer)
  const innTalk = char => (text, options, onPick) => options ? shrineAsk(text, options, onPick, char) : speak(char, text);
  function talkToInnkeeper(npc, K) {
    if (Date.now() - lastModal < 450 || talkBusy()) return;
    if (!K.talks) { window.wdnInnRest(innTalk(K.char)); return; }
    shrineAsk("Welcome to the Cave Inn! Would you like a room?", ["Rest", "Talk", "Leave"], v => {
      if (v === 0) setTimeout(() => { try { window.wdnInnRest(innTalk(K.char)); } catch (e) {} }, 650);
      else if (v === 1) setTimeout(() => { try { npc.__wdnTalkNow = true; npc.onInteraction(); } catch (e) {} }, 650);
    }, K.char);
  }
  let duelNpc = null, duelPlayer = null, pendingTalk = null;
  window.wdnIsCardPlayer = npc => !!npcPlayer(npc);   // for the minimap and area map
  window.wdnCardPlayerSpots = () => duelsOn() ? CARD_PLAYERS.map(P => ({ map: P.map, x: P.x + 8, y: P.y + 8, name: P.name })) : [];
  if (window.ig && ig.ENTITY && ig.ENTITY.NPC) {
    ig.ENTITY.NPC.inject({
      init(a, b, c, d) { this.__wdnSpawn = { x: a, y: b }; this.parent(a, b, c, d); },
      // the silent desk clerks get a speech bubble so they can be talked to
      updateNpcState(a, b) {
        const r = this.parent(a, b);
        try { if (this.activeStateIdx >= 0 && !this.hidden && (innkeeper(this) || this.__wdnFigure)) sc.mapInteract.addEntry(this.interactEntry); } catch (e) {}
        return r;
      },
      onInteraction() {
        if (this.__wdnFigure) {   // the mod's own people: the card collector and the rival
          if (Date.now() - lastModal > 450 && !(ig.game.events && ig.game.events.blockingEventCall)) { try { this.__wdnFigure(); } catch (e) { console.error("[CrossCode Enhanced] figure", e); } }
          return;
        }
        const K = !this.__wdnTalkNow && innkeeper(this);
        if (K) { try { talkToInnkeeper(this, K); return; } catch (e) { console.error("[CrossCode Enhanced] innkeeper", e); } }
        const P = npcPlayer(this);
        if (!P || this.__wdnTalkNow) { this.__wdnTalkNow = false; return this.parent(); }
        try {
          if (!defineCards() || !defineDuels()) return this.parent();
          duelNpc = this; duelPlayer = P;
          cardLabels();
          sc.menu.setDirectMode(true, DUEL_MENU_ID);
          sc.model.enterMenu(true);
          sc.model.prevSubState = sc.GAME_MODEL_SUBSTATE.RUNNING;
          return;
        } catch (e) { console.error("[CrossCode Enhanced] card hall", e); return this.parent(); }
      }
    });
  }
  // "Talk": once the menu has closed, run the person's own conversation
  setInterval(() => {
    try {
      if (!pendingTalk || !sc.model.isGame() || (sc.model.isMenu && sc.model.isMenu())) return;
      const npc = pendingTalk; pendingTalk = null;
      npc.__wdnTalkNow = true;
      npc.onInteraction();
    } catch (e) { pendingTalk = null; }
  }, 100);
  // =====================================================================================================
  // ---------- figures of the mod's own: the card collector, the rival and the orb shrines ----------
  // Each is a prop of the mod's own (data/props/wdn-props.json, pictures in media/map/) placed while you're
  // in its room, with a speech bubble to talk to it.
  // =====================================================================================================
  const placed = {};   // id -> { ent, entry, map }
  function placeFigure(id, want, propName, talk, char) {
    try {
      const map = mapNow(), P = placed[id];
      if (P && (!want || want.map !== map || ig.game.entities.indexOf(P.ent) < 0)) {
        try { sc.mapInteract.removeEntry(P.entry); } catch (e) {}
        try { if (P.ent && !P.ent._killed && ig.game.entities.indexOf(P.ent) >= 0) P.ent.kill(); } catch (e) {}
        delete placed[id];
      }
      if (placed[id] || !want || want.map !== map || !ig.game.playerEntity) return;
      // (right after a door the new room's levels may not be set up yet: wait for the next check)
      if (!ig.game.levels || !ig.game.levels[want.lv || 0] || (sc.model.isLoading && sc.model.isLoading())) return;
      let z = 0; try { z = ig.game.getHeightFromLevelOffset ? ig.game.getHeightFromLevelOffset(want.lv || 0) || 0 : 0; } catch (e) { return; }
      if (char && ig.ENTITY.NPC) {   // a person: one of the game's own townsfolk sprites
        const ent = ig.game.spawnEntity(ig.ENTITY.NPC, want.x, want.y, z, { name: "wdn-" + id, characterName: char,
          npcStates: [{ reactType: "FIXED_POS", face: want.face || "SOUTH", action: [], hidden: false, condition: "", config: "normal", event: [] }] });
        ent.__wdnFigure = talk;
        try { if (ent.interactEntry) sc.mapInteract.addEntry(ent.interactEntry); } catch (e) {}
        placed[id] = { ent, entry: ent.interactEntry, map };
        return;
      }
      const ent = ig.game.spawnEntity(ig.ENTITY.Prop, want.x, want.y, z, { name: "wdn-" + id, propType: { sheet: "wdn-props", name: propName } });
      const icon = ig.ENTITY.NPC && ig.ENTITY.NPC.prototype.interactIcons ? ig.ENTITY.NPC.prototype.interactIcons.normal : null;
      const entry = new sc.MapInteractEntry(ent, {
        onInteraction() { if (Date.now() - (window.wdnLastModal ? window.wdnLastModal() : 0) > 450) { try { talk(); } catch (e) { console.error("[CrossCode Enhanced] " + id, e); } } },
        onInteractionEnd() {}, isInteractionBlocked() { return false; }
      }, icon, sc.INTERACT_Z_CONDITION.Z_RANGE_OVERLAP, true);
      sc.mapInteract.addEntry(entry);
      placed[id] = { ent, entry, map };
    } catch (e) { console.error("[CrossCode Enhanced] " + id, e); delete placed[id]; }
  }
  const visitedAreas = () => { try { return Object.keys(sc.map.areas || {}).filter(areaVisited); } catch (e) { return []; } };
  // a character speaking in the game's own message boxes, with their face and name; skipped like any other talk
  // (the button that moves the talk on would also count as talking to them again, and every one of those queued
  // another talk after this one, so it never seemed to end: only one talk at a time, and a moment's pause after)
  let talkCall = null, talkEnded = 0;
  const talkBusy = () => (talkCall && talkCall.isRunning && talkCall.isRunning()) || Date.now() - talkEnded < 500 || !!(ig.game.events && ig.game.events.blockingEventCall);
  function speak(char, text) {
    if (talkBusy()) return;
    try {
      // the speakers join the conversation first (Lea on the right, them on the left), as the game's own talks do
      const steps = [
        { type: "ADD_MSG_PERSON", side: "RIGHT", order: 0, clearSide: false, person: { person: "main.lea", expression: "DEFAULT" } },
        { type: "ADD_MSG_PERSON", side: "LEFT", order: 0, clearSide: false, person: { person: char, expression: "DEFAULT" } }
      ].concat([].concat(text).map(t => ({ type: "SHOW_MSG", message: { en_US: t, langUid: 0 }, person: { person: char, expression: "DEFAULT" }, autoContinue: false })));
      // a talk is a little cutscene: the game only reads the button that moves talk boxes on while in one
      talkCall = ig.game.events.callEvent(new ig.Event({ name: "wdnTalk", steps }), ig.EventRunType.BLOCKING,
        () => { try { sc.model.enterCutscene(false); } catch (e) {} },
        () => { try { sc.model.enterGame(); } catch (e) {} talkEnded = Date.now(); talkCall = null; });
    } catch (e) { console.error("[CrossCode Enhanced] speak", e); sc.Dialogs.showInfoDialog([].concat(text).join(" "), true); }
  }

  // ---- the card collector (Rookie Harbor plaza): a reward every 25 cards, and the big one at all 185 ----
  // by the red market stall on the south-west side of the plaza
  const COLLECTOR_SPOT = { map: "rookie-harbor.center", x: 770, y: 1100, lv: 1, face: "SOUTH" };
  // the mod's own characters (data/characters/wdn/): the game's businessman and blond Triblader, with names
  const COLLECTOR_CHAR = "wdn.collector", RIVAL_CHAR = "wdn.rival";
  const COLLECT_STEPS = [
    { n: 25, cr: 1000, pack: "basic" }, { n: 50, cr: 2000, pack: "rare" }, { n: 75, cr: 3000, pack: "rare" },
    { n: 100, cr: 4000, pack: "holo" }, { n: 125, cr: 5000, pack: "holo" }, { n: 150, cr: 6000, pack: "holo" },
    { n: 175, cr: 8000, pack: "holo", two: true }
  ];
  let collector = { got: {}, master: false };
  try {
    modStore({
      onStorageSave(save) { try { save.wdnCollector = JSON.parse(JSON.stringify(collector)); } catch (e) {} },
      onStoragePreLoad(file) { collector = Object.assign({ got: {}, master: false }, JSON.parse(JSON.stringify((file && file.wdnCollector) || {}))); }
    });
  } catch (e) {}
  window.wdnMasterCollector = () => !!collector.master;
  const collectorOn = () => duelsOn() && opt("cardCollector", true) !== false;
  function collectorTalk() {
    const have = cardList().filter(hasCard).length, total = cardList().length;
    const due = COLLECT_STEPS.filter(s => have >= s.n && !collector.got[s.n]);
    const P = { areas: visitedAreas() };
    if (due.length) {
      let cr = 0, cards = 0;
      for (const s of due) {
        collector.got[s.n] = 1; cr += s.cr;
        const pack = PACKS.find(p => p.id === s.pack);
        for (let t = 0; t < (s.two ? 2 : 1); t++) for (const c of openPack(pack, P)) { addCopies(c.key, 1, true, c.arrows); cards++; }
      }
      try { sc.model.player.addCredit(cr); } catch (e) {}
      try { sc.BUTTON_SOUND.shop_cash.play(); } catch (e) {}
      toastQueue.push({ type: "note", icon: "credits", head: "\\c[3]COLLECTOR'S REWARD\\c[0]", title: have + " cards collected!", sub: "\\c[4]+" + cr + " Credits and " + cards + " cards\\c[0]" });
      speak(COLLECTOR_CHAR, "Oh! " + have + " cards! Here, take these: " + cr + " Credits and " + cards + " cards from my spares. Come back at " + ((COLLECT_STEPS.find(s => !collector.got[s.n]) || { n: total }).n) + "!");
      return;
    }
    if (have >= total && !collector.master) {
      collector.master = true;
      try { sc.model.player.addCredit(20000); } catch (e) {}
      toastQueue.push({ type: "note", icon: "star", head: "\\c[3]MASTER COLLECTOR\\c[0]", title: "Every card collected!", sub: "\\c[4]+20000 Credits  -  every card now has a collector's gold frame\\c[0]" });
      speak(COLLECTOR_CHAR, "All " + total + "... I never thought I'd see it. You're a true Master Collector. Every card of yours deserves a gold frame - and these 20000 Credits.");
      return;
    }
    if (collector.master) { speak(COLLECTOR_CHAR, "The Master Collector herself! Your collection is the finest on Shadoon."); return; }
    const next = COLLECT_STEPS.find(s => !collector.got[s.n]) || { n: total };
    speak(COLLECTOR_CHAR, "I reward every serious collector. You have " + have + " of " + total + " cards. Bring me " + next.n + " and I'll make it worth your while.");
  }

  // ---- the rival: turns up in a newer town as Lea grows, and gets better every time you beat them ----
  const RIVAL_TOWNS = [
    { area: "rookie-harbor", map: "rookie-harbor.center", x: 648, y: 952, lv: 1, from: 1, face: "EAST" },
    { area: "bergen", map: "bergen.bergen", x: 572, y: 1290, lv: 1, from: 18 },
    { area: "heat-village", map: "heat-village.baki-2", x: 816, y: 484, lv: 1, from: 32 },
    { area: "jungle-city", map: "jungle-city.center", x: 784, y: 1596, lv: 0, from: 46 }
  ];
