      T((st.done ? "\\c[3]" : "") + st.name + (st.done ? "\\c[0]" : ""), small, x + 14, yy - 1);
      const t = T(st.id === "h" ? (st.done ? "\\c[2]beaten\\c[0]" : "\\c[4]not yet\\c[0]") : (st.done ? "\\c[2]" : "\\c[4]") + st.have + "/" + st.need + "\\c[0]", sc.fontsystem.tinyFont, 0, yy);
      t.setPos(x + w - t.hook.size.x, yy);
