    if ((hideDone || hideHeard) && !hideNorthOpen() && sc.model.isGame()) { hideDone = false; hideHeard = false; hideSeen = false; }
    if (m !== HIDE_MAP) { if (hideQuest) hideQuestStop(); return; }
    if (hideDone || riftTeleporting() || !sc.model.isGame()) return;
