  const GEROLD = { map: "rookie-harbor.north", x: 1096, y: 752, lv: 2, face: "SOUTH" }, GEROLD_CHAR = "wdn.gerold";
  const HUB_MAP = "rookie-harbor.central-quest-hub", HUB_BOARD = { x: 724, y: 268 };
