  // ---------- Expeditions: companions you aren't using go exploring ----------
  // Three slots. Choose a companion card (not the one equipped), an area you've been to, and how long
  // (in-game hours: rests at inns count). Back home: Credits, cards from that area, and bond for it. Rough
  // weather in that area when it comes back pays a third more.
  const EXP_MENU_ID = 249, EXP_LENS = [{ name: "Short", h: 2 }, { name: "Medium", h: 6 }, { name: "Long", h: 12 }];
  let expSlots = [null, null, null];
  try {
    modStore({
      onStorageSave(save) { try { save.wdnExp = JSON.parse(JSON.stringify(expSlots)); } catch (e) {} },
      onStoragePreLoad(file) { const x = file && file.wdnExp; expSlots = Array.isArray(x) ? [0, 1, 2].map(i => x[i] || null) : [null, null, null]; }
    });
  } catch (e) {}
  const expNow = () => window.wdnAbsMinutes ? window.wdnAbsMinutes() : Date.now() / 60000;
  function expAway(key) { return expSlots.some(x => x && x.key === key); }
  function expLeft(x, now) { const m = Math.max(0, Math.ceil(x.end - now)); return m >= 60 ? Math.floor(m / 60) + "h " + String(m % 60).padStart(2, "0") + "m" : m + "m"; }
  // what can go, and where
  function expCompanions() { const eq = currentEquip(); return cardList().filter(k => hasCard(k) && compAllowed(k) && !expAway(k) && !(eq && eq.key === k)); }
  function expAreas() {
    const seen = new Set();
    for (const k of cardList()) { const a = enemyDb()[k].area; if (a && a !== "fallback" && areaVisited(a)) seen.add(a); }
    return [...seen];
  }
  function expRough(area) { const w = window.wdnAreaWeather && window.wdnAreaWeather(area); return !!(w && /storm|blizzard|sandstorm|downpour/.test(w.weather)); }
  function expSend(i, key, area, len) {
    const now = expNow();
    expSlots[i] = { key, area, h: EXP_LENS[len].h, start: now, end: now + EXP_LENS[len].h * 60 };
    try { sc.BUTTON_SOUND.submit.play(); } catch (e) {}
  }
  // home again: Credits, cards (new ones or spares) from that area's monsters, and bond
  function expCollect(i) {
    const x = expSlots[i];
    if (!x || expNow() < x.end) return;
    expSlots[i] = null;
    const rough = expRough(x.area), mult = rough ? 1.33 : 1, lv = leaLevel();
    const credits = Math.round(40 * x.h * (1 + lv / 20) * mult);
    try { sc.model.player.addCredit(credits); } catch (e) {}
    const pool = cardList().filter(k => enemyDb()[k].area === x.area && !enemyDb()[k].boss), got = [];
    const rolls = Math.max(1, Math.round(x.h / 3 * mult));
    for (let r = 0; r < rolls && pool.length; r++) {
      if (Math.random() > 0.6) continue;
      const k = pool[Math.floor(Math.random() * pool.length)];
      // (quietly: the one pop-up below lists them)
      if (cardGot[k]) addCopies(k, 1, true);
      else { const day = window.wdnDay ? window.wdnDay() : null; cardGot[k] = { d: day, s: 0, f: 0, n: 1 }; try { checkAreas(); } catch (e) {} }
      got.push(cardInfo(k).name);
    }
    const newLv = addBond(x.key, x.h * 3, true);
    // the same card twice reads "Hillkat x2"
    const counts = {}; for (const n of got) counts[n] = (counts[n] || 0) + 1;
    const list = Object.keys(counts).map(n => n + (counts[n] > 1 ? " x" + counts[n] : ""));
    toastQueue.push({ type: "note", key: x.key, head: "\\c[3]EXPEDITION BACK\\c[0]", title: cardInfo(x.key).name + " is back from " + areaLabel(x.area),
      sub: "\\c[4]+" + credits + " Credits" + (list.length ? ", cards: " + list.join(", ") : ", no cards this time") + ", +" + bondGain(x.h * 3) + " bond" + (newLv ? " (now Lv " + newLv + ")" : "") + (rough ? ". Rough weather: a third more" : "") + "\\c[0]" });
  }
