        r.addColor(GOLD_TRACK, 32, 54, 504, 1).setAlpha(0.8);
        r.addColor(GOLD_TRACK, 32, 204, 504, 1).setAlpha(0.5);
        if (this.heads) SKILL_BRANCHES.forEach((B, i) => skillIcon(r, ["skill", B.icon], this.heads[i], 58, true));
        // the branches' lines, lit as far as you've got
