          const x = COLX(k.branch), y0 = ROWY(k.tier - 1) + 14, y1 = ROWY(k.tier) - 14, lit = perk(k.id) || (perk(SKILLS.find(o => o.branch === k.branch && o.tier === k.tier - 1).id));
