    const VAN = [{ x: 4, y: 43 }, { x: 12, y: 73 }, { x: 20, y: 103 }, { x: 28, y: 133 }, { x: 28, y: 163 }, { x: 20, y: 193 }, { x: 12, y: 223 }, { x: 4, y: 253 }];
    const VAN_NAMES = ["quest", "skills", "equipment", "items", "social", "status", "synopsis", "save"];
    const NEW_ORDER = ["quest", "skills", "equipment", "items", "social", "status", "synopsis", "wdnEnhanced", "save"];
    const NEW_ARC = [4, 10, 16, 22, 28, 22, 16, 10, 4], NEW_Y0 = 40, NEW_DY = 27;
