  // For the slot it goes in (for weapons: the weaker hand, the one you'd swap out), the change in HP, Attack,
  // Defense and Focus. UPGRADE when nothing goes down and something goes up.
  function gearCompare(id) {
    const G = gearParts(id);
    if (!G) return "";
    return G.arm ? "  \\c[3]Main\\c[0] " + G.main + "  \\c[4]|\\c[0]  \\c[3]Off\\c[0] " + G.off : "  " + G.one;
  }
  function gearParts(id) {
    try {
      const it = sc.inventory.getItem(id);
      if (!it || it.type !== sc.ITEMS_TYPES.EQUIP || !it.params) return "";
      const E = sc.model.player.equip, T = sc.ITEMS_EQUIP_TYPES, P = ["hp", "attack", "defense", "focus"], W = ["HP", "ATK", "DEF", "FOC"];
      // the change against what's in one slot: "+12ATK -3DEF", with UPGRADE when it's better all round
      const vs = cur => {
        if (cur === id) return "\\c[4]worn\\c[0]";
        const o = cur >= 0 ? sc.inventory.getItem(cur) : null, op = (o && o.params) || {};
        let up = 0, down = 0;
        const bits = [];
        P.forEach((p, i) => {
          const d = (it.params[p] || 0) - (op[p] || 0);
          if (!d) return;
          if (d > 0) up++; else down++;
          bits.push((d > 0 ? "\\c[2]+" : "\\c[1]") + d + "\\c[0]\\c[4]" + W[i] + "\\c[0]");
        });
        if (!bits.length) return "\\c[4]same stats\\c[0]";
        return bits.join(" ") + (up && !down ? " \\c[3]UPGRADE\\c[0]" : "");
      };
      // weapons: both hands, the main hand (right) first
      if (it.equipType === T.ARM) return { arm: true, main: vs(E.rightArm), off: vs(E.leftArm) };
      const cur = it.equipType === T.HEAD ? E.head : it.equipType === T.TORSO ? E.torso : it.equipType === T.FEET ? E.feet : -1;
      return { arm: false, one: vs(cur), part: it.equipType };
    } catch (e) { return null; }
  }
