          this.textGui.setText("\\i[" + ((it.icon || "item-default") + sc.inventory.getRaritySuffix(it.rarity || 0)) + "]" + ig.LangLabel.getText(it.name) + extra + "  x");
          const big = sc.options.get("item-hud-size") == sc.ITEM_HUD_SIZE.NORMAL;
