              // the player steering away from it (the angle between their aim and the enemy growing fast): let go
              if (T && aimPrevAng && aimPrevAng.e === T.e && T.ang - aimPrevAng.ang > 0.012 && T.ang > L.cone * 0.4) { aimLetGo.set(T.e, Date.now() + 1200); T = null; }
              aimPrevAng = T ? { e: T.e, ang: T.ang } : null;
