          if (aimFoe && !aimFoe._killed) a.__wdnLastT = { x: aimFoe.coll.pos.x + aimFoe.coll.size.x / 2, y: aimFoe.coll.pos.y + aimFoe.coll.size.y / 2 };
          if (!a.__wdnLastT || (!aimRamp && Math.abs(a.__wdnOff || 0) < 0.002)) { aimFoe = null; a.__wdnOff = 0; a.__wdnLastT = null; return; }
          // turn the aim towards it (by angle, so the throw direction really bends), keeping roughly the same reach
          const k = (L ? L.pull : 0.5) * aimRamp * aimRamp * (3 - 2 * aimRamp);   // (eased)
          const tx = T ? T.x : a.__wdnLastT.x, ty = T ? T.y : a.__wdnLastT.y;   // (a foe that just died: where it was)
          const rx = a.coll.pos.x - tc.x, ry = a.coll.pos.y - tc.y, rl = Math.hypot(rx, ry), fx = tx - tc.x, fy = ty - tc.y, fl = Math.hypot(fx, fy);
          if (rl < 4 || fl < 4) return;
          let ra = Math.atan2(ry, rx), d = Math.atan2(fy, fx) - ra;
          while (d > Math.PI) d -= 2 * Math.PI; while (d < -Math.PI) d += 2 * Math.PI;
          // the game widens the aim (and replays the "charged" sound) when the aim turns more than ~2.8 degrees in a
          // frame, so the pull itself may only change by a small step each frame: switching enemies glides over
          const want = d * k, prev = a.__wdnOff || 0, step = 0.012 * Math.max(0.5, dt * 60);
