      if (!window.ig || !ig.gui || !sc.TitleScreenGui || !sc.model || !sc.model.isTitle || !sc.model.isTitle()) return;
      const T = ig.gui.guiHooks.map(h => h.gui).find(g => g instanceof sc.TitleScreenGui);
      const P = T && T.bgGui, G = P && P.gui;
