        return { x: Math.random() * (W + 60) - 30, y: any ? Math.random() * H : -6 - Math.random() * 40, v: 0.6 + Math.random() * 0.8,
          ph: Math.random() * 6.28, spin: 1 + Math.random() * 2, c: Math.floor(Math.random() * 3), big: Math.random() < 0.3 };
