        this.head = new sc.TextGui("", { font: sc.fontsystem.font }); this.head.setPos(PX + 8, PY + 4); this.addChildGui(this.head);
        this.hint = new sc.TextGui("\\c[4]\\i[circle-left]\\i[circle-right] scroll\\c[0]", { font: sc.fontsystem.tinyFont }); this.addChildGui(this.hint);
        this.hint.setPos(PX + PW - 8 - this.hint.hook.size.x, PY + 8);
