          const a = new sc.TextGui(name, { font: sc.fontsystem.smallFont }); a.setPos(X, y); body.addChildGui(a); y += a.hook.size.y + 1;
          const b = new sc.TextGui("\\c[4]" + text + "\\c[0]", { font: sc.fontsystem.tinyFont, maxWidth: PW - 26 - X }); b.setPos(X + 2, y); body.addChildGui(b); y += b.hook.size.y;
          y = Math.max(y, top + (icon ? 34 : 0)) + 8;
