    const P = sc.model.player, V = ig.vars;
    const snap = ig.copy(V.storage); delete snap.map; delete snap.session; delete snap.tmp;
    replay = { D, boss, snap, items: keyItemCounts(), sp: (P.skillPoints || []).slice(), spx: (P.skillPointsExtra || []).slice(),
      party: (sc.party.currentParty || []).slice(), back: leaSpot(), t0: Date.now(), won: false, bossKey: mapKey(D.boss[0]) };
    // the dungeon forgets it was ever solved: its rooms (or just the boss's room) and its own switches
